#!/usr/bin/env python3
"""Lossless PR115 publication assembly from sealed evidence and postmerge reads."""
from pathlib import Path,PurePosixPath
from datetime import datetime,timezone
import json,hashlib,tarfile,shutil,traceback,os
ROOT=Path(__file__).resolve().parent
BASE=ROOT.parent
ARCHIVE=BASE/'agent12-review115-publication-001.tar.xz'
def sha(d):return hashlib.sha256(d).hexdigest()
def blob(d):return hashlib.sha1(b'blob '+str(len(d)).encode()+b'\0'+d).hexdigest()
def dump(n,x):(ROOT/n).write_text(json.dumps(x,indent=2)+'\n')
def main():
 (ROOT/'sealed-archives').mkdir(exist_ok=False)
 sources=[('agent12-review115-evidence.tar.xz','093b6c5f70442710dcf7ec512a86dfc7787c983039b764d49fd0bf1d32d2c569','fresh-review',''),('agent12-review115-combination-d0013552.tar.xz','85eb6a4e06b8169b3a195f44eca8c04db32b8e7601898b8d718b04e9e9e18983','combination','review115-current-main-combination-001/')]
 source_inventory=[]
 for filename,expected,dest,prefix in sources:
  source=BASE/filename;archive_bytes=source.read_bytes();assert sha(archive_bytes)==expected
  (ROOT/'sealed-archives'/filename).write_bytes(archive_bytes)
  records=[];seen=set()
  with tarfile.open(source,'r:xz') as tf:
   for m in tf:
    pp=PurePosixPath(m.name);assert m.isfile() and not pp.is_absolute() and '..' not in pp.parts and m.name not in seen
    seen.add(m.name);assert m.name.startswith(prefix);relative=m.name[len(prefix):];assert relative
    rp=PurePosixPath(relative);assert not rp.is_absolute() and '..' not in rp.parts
    target=ROOT/dest/relative;target.parent.mkdir(parents=True,exist_ok=True);assert not target.exists()
    data=tf.extractfile(m).read();assert len(data)==m.size;target.write_bytes(data);target.chmod(m.mode & 0o777)
    records.append({'source_member':m.name,'original_mode':m.mode,'bytes':len(data),'sha256':sha(data),'publication_member':target.relative_to(ROOT).as_posix()})
  manifest=json.loads((ROOT/dest/'DELIVERY_MANIFEST.json').read_text())
  listed=manifest['files'] if dest=='fresh-review' else manifest['retained_files']
  if isinstance(listed,dict):listed=[{'path':k,**v} for k,v in listed.items()]
  for x in listed:
   d=(ROOT/dest/x['path']).read_bytes();assert len(d)==x['bytes'] and sha(d)==x['sha256']
  source_inventory.append({'archive':filename,'bytes':len(archive_bytes),'sha256':expected,'git_blob_sha1':blob(archive_bytes),'publication_archive_member':'sealed-archives/'+filename,'original_archive_preserved_byte_for_byte':True,'all_members_expanded_and_verified':True,'member_count':len(records),'members':records})
 dump('SOURCE_ARCHIVES.json',source_inventory)
 # Direct publication files are exact copies; full original context also remains.
 direct={'SEMANTIC_REVIEW.md':'fresh-review/SEMANTIC_REVIEW.md','FRESH_REVIEW_RECEIPT.json':'fresh-review/RECEIPT.json','COMBINATION_RECEIPT.json':'combination/COMBINATION_RECEIPT.json','POSTMERGE_IDENTITY.json':'postmerge/POSTMERGE_IDENTITY.json','SOURCE_BINDINGS.json':'postmerge/SOURCE_BINDINGS.json','PACKAGE_BINDINGS.json':'postmerge/PACKAGE_BINDINGS.json','VERIFIER_METADATA_BINDINGS.json':'postmerge/VERIFIER_METADATA_BINDINGS.json'}
 for dest,source in direct.items():(ROOT/dest).write_bytes((ROOT/source).read_bytes())
 post=json.loads((ROOT/'POSTMERGE_IDENTITY.json').read_text());fresh=json.loads((ROOT/'FRESH_REVIEW_RECEIPT.json').read_text());comb=json.loads((ROOT/'COMBINATION_RECEIPT.json').read_text())
 assert post['status'].startswith('PASS') and fresh['verdict'].startswith('PASS') and comb['status'].startswith('PASS')
 assert not (ROOT/'postmerge/helper.stderr.log').read_bytes()
 dump('postmerge/HELPER_EXECUTION.json',{'argv':['python',str(ROOT/'postmerge/verify_postmerge.py')],'exit_code':0,'stdout':'helper.stdout.log','stderr':'helper.stderr.log','remote_mutations':False,'source_mutations':False,'git_ref_mutations':False})
 inherited_omissions=json.loads((ROOT/'fresh-review/DELIVERY_MANIFEST.json').read_text())['omitted_reproducible_objects']
 assert len(inherited_omissions)==20 and all(p.endswith('.olean') for p in inherited_omissions)
 evidence=json.loads((ROOT/'fresh-review/EVIDENCE_AUDIT.json').read_text())
 aggregate={'schema_version':1,'status':'PASS_READY_FOR_POSTMERGE_PUBLICATION','publication_kind':'Independent nonauthor exact-source semantic/kernel/evidence review with postmerge identity bindings','created_utc':datetime.now(timezone.utc).isoformat(),'repository':'taco-jpg/p196-algorithm','pull_request':115,'exact_head':fresh['exact_head'],'source_freeze':fresh['source_freeze'],'actual_merge_commit':post['actual_merge_commit'],'actual_merge_ordered_parents':post['actual_merge_ordered_parents'],'actual_merge_tree':post['actual_merge_tree'],'observed_current_main':post['observed_current_main'],'observed_current_main_tree':post['observed_current_main_tree'],'current_main_observed_at':post['current_main_observed_at'],'merge_attribution':post['merge_attribution'],'fresh_full_module_builds':1,'strict_compiler_flags':['--trust=0','-j1','-DElab.async=false'],'fresh_kernel_verification':{k:fresh[k] for k in ['module_count','theorem_constants','safe_definitions','safe_opaque','closure_public_theorem_exports','explicit_named_declarations','literal_new_public_theorem_exports','all_origin_constants','allowed_transitive_math_axioms']},'new_lean_runs_in_combination_or_postmerge':0,'exact_current_main_bindings':{'mathematical_sources':20,'package_files':234,'registry_replay_dependency_publication_and_pinned_verifier':True},'sealed_source_archives_unchanged':True,'all_original_archive_members_preserved':True,'source_archives_manifest':'SOURCE_ARCHIVES.json','direct_publication_files':direct,'current_reproducible_compiled_object_exclusions':20,'historical_explicit_compiled_object_exclusions':evidence['historical_compiled_objects_explicitly_excluded'],'source_log_helper_or_failure_exclusions':0,'remote_mutations':False,'source_mutations':False,'git_ref_mutations':False,'uploaded':False,'publication_readiness':'Complete English documents and receipts, full raw evidence, original failures, source and verifier snapshots, actual merge/current-main API and Git readbacks, lossless manifests, and an independently roundtripped archive are prepared. Parent decides publication; no upload performed.'}
 dump('RECEIPT.json',aggregate)
 (ROOT/'README.md').write_text(f'''# PR115 independent review and postmerge publication package\n\n## Result and attribution\n\n**PASS.** This package preserves a genuine independent nonauthor review of exact head `{fresh['exact_head']}`, including a fresh full strict 20-module Lean build, exhaustive origin/axiom checks, semantic review, evidence-integrity audit, fixed-base combination check and actual postmerge readbacks. All durable reports and helper code are in English. The reviewer is Agent #12's delegated nonauthor reviewer `/root/review123`, operating in the same collaborative workspace; this is not presented as unrelated external peer review or a separate-account approval.\n\nPR115 had already been merged by another workflow at `{post['actual_merge_commit']}` on `{post['merged_at']}`. GitHub's API reports merged=true, state=closed and merged_by=`{post['api_merged_by']}`. Neither this reviewer nor Agent #12 claims to have performed that merge. This package performs no remote mutation, comment, review submission, main claim or upload.\n\n## Direct publication files\n\n| File | Purpose |\n|---|---|\n| `SEMANTIC_REVIEW.md` | Full original English mathematical and evidence review, preserved byte for byte. |\n| `RECEIPT.json` | Aggregate publication receipt and exact identities. |\n| `FRESH_REVIEW_RECEIPT.json` | Original fresh strict review receipt, preserved byte for byte. |\n| `POSTMERGE_IDENTITY.json` | Actual merge parents/tree, API state, observed main identity and ancestry. |\n| `SOURCE_BINDINGS.json` | All 20 source paths, sizes, Git blobs, SHA256 and H/M/current-main bindings to fresh compiler inputs. |\n| `VERIFIER_METADATA_BINDINGS.json` | Registry, original replay, dependency/publication records and pinned verifier identities. |\n| `PACKAGE_BINDINGS.json` | All 234 exact-head package files bound to merge and observed main. |\n| `COMBINATION_RECEIPT.json` | Prior fixed-base already-contained identity-combination result. |\n| `SOURCE_ARCHIVES.json` | Exact sealed archive identities and every original member's size/hash/publication mapping. |\n| `MANIFEST.json` | All publication files and explicit compiled-object exclusions. |\n\n## Fresh strict kernel verification\n\nAll 20 modules were rebuilt from fresh project source snapshots into an initially empty project-object directory. Every module and both audit commands explicitly used `--trust=0 -j1 -DElab.async=false`. No author or prior reviewer project `.olean` was reused. The pinned official runtime was Lean 4.19.0, commit 6caaee842e94, executable SHA256 `92c3d35b5bfaa5e0fea413a775d504cf46cd95e1345df61c2274f76779e7e023`. Its original supply tar is unavailable; no fresh tar download or fresh archive verification is claimed. Runtime identities before/after are retained.\n\nThe accepted fresh gate covers 713 theorem constants, 266 safe definitions, zero opaque declarations, 276 closure public theorem exports, 383 named declarations with types and literal axioms, 29 new public theorem exports, and a complete census of 1,470 origin constants. Structured and full multiline literal reports agree for all 979 theorem/safe-definition declarations. The mathematical axiom union is exactly Classical.choice, Quot.sound and propext. Generated unsafe implementation definitions and inherited unsafe implementation axioms are separately inventoried.\n\nThe original portable `replay.py` is preserved unchanged. Its canonical module build does not explicitly pass trust=0; its subsequent new-export audit does. The separately attributed `compile_strict.py` and `audit_strict.py` provide this publication's fresh explicit-trust-zero full-closure gate. Neither the combination nor postmerge supplement claims a second Lean run. Their use of the fresh gate is justified by exact source and verifier byte identities.\n\n## Mathematical scope\n\nOriginal certificate acceptance implies the existing normalized row states form a closed exterior orbit, have zero signed contribution sum, and contain both strict contribution signs. The executable coordinate filter is necessary and preserves the original checker's Boolean result when conjoined with it, including zero-period and phase-zero boundaries. The retained -11/+11 cancellation candidate passes the filter yet fails the original phase transition, establishing that the filter is insufficient.\n\nThe weighted balance counts the normalized nonzero carry indicator. It is not identified with legacy `totalGam`; the separate bridge owned by PR137 is not assumed. No accepted certificate instance, realized infinite integer orbit, global cycle exclusion or 196 claim is introduced.\n\n## Actual merge and observed main\n\nThe actual ordered parents are:\n\n1. `{post['actual_merge_ordered_parents'][0]}`\n2. `{post['actual_merge_ordered_parents'][1]}` (the exact reviewed H)\n\nThe actual merge tree is `{post['actual_merge_tree']}`. Recomputing the first parent plus H produces that same tree. All {post['first_parent_tracked_entries']} first-parent entries are unchanged and exactly 234 owned package files are added, each identical to H.\n\nAt `{post['current_main_observed_at']}`, the main API readback was `{post['observed_current_main']}`, tree `{post['observed_current_main_tree']}` with {post['current_main_tracked_entries']} tracked entries. The actual merge, reviewed H and earlier fixed combination base are all ancestors. All 234 package files and all 20 fresh compiler source inputs, plus registry/replay/verifier metadata, remain identical at that observed main. This is an immutable timestamped observation, not a claim about future main changes. The mutable PR API base field is not substituted for the actual merge's ordered first parent.\n\nThe earlier fixed-base check used `{comb['base']}`. H was already its ancestor, so its combined tree was identical and its effective delta was zero. It never counted previously integrated PR90 history or PR115 files as a new contribution.\n\n## Complete evidence layout and retention\n\n`fresh-review/` expands every one of the 328 members of the first sealed review. It includes all 234 original exact-head package files, original historical development and independent-review evidence, fresh build/audit source snapshots and raw logs, all drivers/adaptation diffs, original manifests, source identities, runtime provenance and current failure records.\n\n`combination/` expands all 71 members of the separately sealed fixed-base supplement, including complete tree inventories, all Git outputs, exact helper source and bindings. `postmerge/` contains the newly retrieved unmodified API JSON, complete connector readback wrappers, actual Git commit/tree/ancestry outputs, helper and identities.\n\nBoth prior sealed archive files are also retained byte for byte under `sealed-archives/`. Thus this publication neither requires the reader to reconstruct a previous archive nor drops its original member bytes. Exact duplicates are retained literally and identified through size/SHA/member mappings; `MANIFEST.json` additionally marks canonical identical-byte members for convenience.\n\nThe first review explicitly omitted only 20 reproducible fresh `.olean` files, preserving each object's size/hash and the complete reproduction evidence. The historical source evidence had separately declared 37 omitted compiled objects; those original declarations and hashes remain preserved. This assembly introduces no additional omission. No source, log, failure, helper or receipt is excluded.\n\nThe original transient HTTP502 retrieval failures and successful retries remain intact. The independent postcheck's first failed overstrong requirement that every module contain a theorem, and its correction for definition-only TARGET, remain intact. This was an audit-helper correction, not a Lean or mathematical-source change. Historical failed attempts remain accurately classified, never silently rewritten as fresh success.\n\n## Reproduction and limits\n\nThe original exact-head portable replay and registry remain in `fresh-review/exact-head-package/`. The separate strict drivers are in `fresh-review/`, their exact adaptations are retained, and all raw compiler commands/environment/path bindings appear in the fresh compilation and audit records. For a fresh run in a different workspace, relocate the explicit input/runtime/output bindings to corresponding files and a new empty output directory; preserve mathematical and registry bytes and compare their recorded hashes. This is an explanation of the existing driver bindings, not a claim that machine-specific recorded absolute paths are portable unchanged.\n\nPostmerge Git access was read-only against the public repository. Immutable Git object creation/fetching used the explicitly designated memory-backed object directory; no source or Git ref was written. Public GitHub signature verification fields are preserved as API evidence, without claiming independent PGP verification.\n\nThe outer archive is verified by reopening every regular member, rejecting duplicate/traversal/link entries and matching every file's exact bytes and SHA256 to `MANIFEST.json`. The final external delivery record identifies the final archive size, SHA256 and Git blob SHA1; it is external to avoid a self-referential archive digest. Nothing has been uploaded.\n''')
 # Exact duplicate bytes remain literal; record canonical member for transparency.
 files=[];canonical={}
 for p in sorted(ROOT.rglob('*')):
  if p.is_file() and p != ROOT/'MANIFEST.json':
   assert not p.is_symlink();data=p.read_bytes();rel=p.relative_to(ROOT).as_posix();digest=sha(data);key=(len(data),digest)
   item={'path':rel,'bytes':len(data),'sha256':digest}
   if key in canonical:item['identical_bytes_also_at']=canonical[key]
   else:canonical[key]=rel
   files.append(item)
 exclusions=[{'source_member':p,'publication_context':'fresh-review/'+p,**x} for p,x in inherited_omissions.items()]
 manifest={'schema_version':1,'status':'COMPLETE_LOSSLESS_SUBSTANTIVE_PUBLICATION','exact_head':fresh['exact_head'],'actual_merge_commit':post['actual_merge_commit'],'observed_current_main':post['observed_current_main'],'files':files,'file_count_excluding_manifest':len(files),'payload_bytes_excluding_manifest':sum(x['bytes'] for x in files),'exact_duplicates_retained_literally':True,'source_archives_and_every_expanded_member_preserved':True,'new_assembly_omissions':[],'previously_recorded_fresh_compiled_object_exclusions':exclusions,'historical_compiled_exclusion_evidence':'fresh-review/EVIDENCE_AUDIT.json and fresh-review/exact-head-package/verification/independent/COPY_MANIFEST.json','historical_compiled_exclusion_count':37,'source_logs_helpers_failures_excluded':0,'self_digest_policy':'This manifest is included in the archive; the archive and manifest digests are supplied in the external delivery seal.'}
 dump('MANIFEST.json',manifest)
 expected={x['path']:x for x in files};md=(ROOT/'MANIFEST.json').read_bytes();expected['MANIFEST.json']={'bytes':len(md),'sha256':sha(md)}
 with tarfile.open(ARCHIVE,'w:xz',preset=6) as tf:
  for rel in sorted(expected):tf.add(ROOT/rel,arcname='review115-publication-001/'+rel,recursive=False)
 seen=set()
 with tarfile.open(ARCHIVE,'r:xz') as tf:
  for m in tf:
   pp=PurePosixPath(m.name);assert m.isfile() and not pp.is_absolute() and '..' not in pp.parts and pp.parts[0]=='review115-publication-001'
   rel=PurePosixPath(*pp.parts[1:]).as_posix();assert rel in expected and rel not in seen;seen.add(rel);data=tf.extractfile(m).read();assert len(data)==expected[rel]['bytes'] and sha(data)==expected[rel]['sha256']
 assert seen==set(expected)
 for filename,digest,_,_ in sources:assert sha((BASE/filename).read_bytes())==digest
 ad=ARCHIVE.read_bytes();delivery={'status':'PASS_READY_FOR_PUBLICATION_NOT_UPLOADED','publication_root':str(ROOT),'archive':str(ARCHIVE),'archive_bytes':len(ad),'archive_sha256':sha(ad),'archive_git_blob_sha1':blob(ad),'archive_member_count':len(seen),'payload_bytes_excluding_manifest':manifest['payload_bytes_excluding_manifest'],'roundtrip':'PASS_ALL_REGULAR_MEMBER_BYTES_SIZES_SHA256_AND_SAFE_PATHS','source_archives_unchanged':True,'source_archive_expanded_members':{x['archive']:x['member_count'] for x in source_inventory},'manifest':str(ROOT/'MANIFEST.json'),'manifest_sha256':sha(md),'direct_files':{n:{'path':str(ROOT/n),'bytes':(ROOT/n).stat().st_size,'sha256':sha((ROOT/n).read_bytes())} for n in ['README.md','SEMANTIC_REVIEW.md','RECEIPT.json','FRESH_REVIEW_RECEIPT.json','POSTMERGE_IDENTITY.json','SOURCE_BINDINGS.json','VERIFIER_METADATA_BINDINGS.json']},'actual_merge_commit':post['actual_merge_commit'],'actual_merge_ordered_parents':post['actual_merge_ordered_parents'],'actual_merge_tree':post['actual_merge_tree'],'observed_current_main':post['observed_current_main'],'observed_current_main_tree':post['observed_current_main_tree'],'merge_attribution':post['merge_attribution'],'remote_mutations':False,'uploaded':False}
 (BASE/'agent12-review115-publication-001-delivery.json').write_text(json.dumps(delivery,indent=2)+'\n')
 print(json.dumps(delivery,indent=2))
if __name__=='__main__':
 try:main()
 except BaseException:
  (ROOT/'build-publication-failure.log').write_text(traceback.format_exc());raise
